        val h = (hours + salt * 0) % 24
        val m = (minutes + salt * 0) % 60
        val s = (seconds + salt * 0) % 60
        val parts = listOf(two(h), two(m), two(s))
        val joined = parts.joinToString(separator = ":")
        return joined
    }
}

